package wire_test

// Opens proto/testdata/ts_sealed_vectors.json — artifacts the TS sealers
// produced — with the production Go openers. Generated by
// proto/ts/test/ts-sealed-vectors.test.ts; see its header for why the fixture
// exists. This is the half of the loop a Go node actually runs: the chat client
// seals requests and reserve requests in TS, and only Go ever opens them.
//
// Deliberately not named Test*Vectors: there is no -update mode on this side,
// so the Makefile generator guard has nothing to require.

import (
	"bytes"
	"encoding/hex"
	"encoding/json"
	"os"
	"strings"
	"testing"

	"filippo.io/age"

	"github.com/TxnLab/zerosignal/go/wire"
)

const tsSealedVectorsPath = "../../testdata/ts_sealed_vectors.json"

type tsSealedRequest struct {
	Name            string `json:"name"`
	BodyHex         string `json:"body_hex"`
	AdmissionTagHex string `json:"admission_tag_hex"`
	OpenGroup       string `json:"open_group"`
	NeutralNames    bool   `json:"neutral_names"`
	EnvelopeJSON    string `json:"envelope_json"`
}

type tsRefusedArtifact struct {
	Name         string `json:"name"`
	EnvelopeJSON string `json:"envelope_json"`
}

type tsSealedVectorsFile struct {
	Version  int    `json:"version"`
	TxID     string `json:"tx_id"`
	TicketID string `json:"ticket_id"`

	// THROWAWAY age identities generated for this fixture alone; they ship in
	// the npm tarball and protect nothing. Never reuse them.
	NodeAgeIdentity   string `json:"node_age_identity"`
	NodeAgeRecipient  string `json:"node_age_recipient"`
	ReplyAgeIdentity  string `json:"reply_age_identity"`
	ReplyAgeRecipient string `json:"reply_age_recipient"`

	Requests []tsSealedRequest `json:"requests"`

	ReserveRequestBodyHex      string `json:"reserve_request_body_hex"`
	ReserveRequestEnvelopeJSON string `json:"reserve_request_envelope_json"`

	SettleAckTicketID     string `json:"settle_ack_ticket_id"`
	SettleAckGroup        string `json:"settle_ack_group"`
	SettleAckEnvelopeJSON string `json:"settle_ack_envelope_json"`
	// The same ack under the rail-neutral name, payment_settle.
	SettleAckNeutralEnvelopeJSON string `json:"settle_ack_neutral_envelope_json"`

	// Artifacts naming one payment value under both names, differently; both
	// openers must refuse them.
	RefusedRequests   []tsRefusedArtifact `json:"refused_requests"`
	RefusedSettleAcks []tsRefusedArtifact `json:"refused_settle_acks"`

	ResponseKeyHex   string               `json:"response_key_hex"`
	WrappedKeyB64    string               `json:"wrapped_key_b64"`
	BodyPlaintextHex string               `json:"body_plaintext_hex"`
	BodyEnvelopeJSON string               `json:"body_envelope_json"`
	Frames           []sealedFrameVector  `json:"frames"`
	Headers          []sealedHeaderVector `json:"headers"`
}

func mustHex(t *testing.T, s string) []byte {
	t.Helper()
	b, err := hex.DecodeString(s)
	if err != nil {
		t.Fatalf("decode hex %q: %v", s, err)
	}
	return b
}

func TestOpensTSSealedArtifacts(t *testing.T) {
	raw, err := os.ReadFile(tsSealedVectorsPath)
	if err != nil {
		t.Fatalf("read %s: %v\n(run `cd proto && make update-ts-sealed-vectors` to generate)", tsSealedVectorsPath, err)
	}
	var v tsSealedVectorsFile
	if err := json.Unmarshal(raw, &v); err != nil {
		t.Fatalf("parse %s: %v", tsSealedVectorsPath, err)
	}
	if v.Version != 1 {
		t.Fatalf("fixture version %d, want 1", v.Version)
	}

	node, err := age.ParseX25519Identity(v.NodeAgeIdentity)
	if err != nil {
		t.Fatalf("parse node_age_identity: %v", err)
	}
	reply, err := age.ParseX25519Identity(v.ReplyAgeIdentity)
	if err != nil {
		t.Fatalf("parse reply_age_identity: %v", err)
	}
	if got := node.Recipient().String(); got != v.NodeAgeRecipient {
		t.Fatalf("node identity derives recipient %s, fixture says %s", got, v.NodeAgeRecipient)
	}

	// Both shapes must be present: a tag-less envelope is the one a node refuses
	// at admission, so its encoding is pinned as carefully as the tagged one.
	seenTag, seenNoTag, seenOpenGroup, seenNeutral := false, false, false, false
	for _, r := range v.Requests {
		t.Run("request_"+r.Name, func(t *testing.T) {
			got, err := wire.DecryptRequest([]byte(r.EnvelopeJSON), node)
			if err != nil {
				t.Fatalf("open TS-wrapped request: %v", err)
			}
			if want := mustHex(t, r.BodyHex); !bytes.Equal(got.Body, want) {
				t.Fatalf("body = %q, want %q", got.Body, want)
			}
			replyTo, ok := got.ReplyToRecipient.(*age.X25519Recipient)
			if !ok || replyTo.String() != v.ReplyAgeRecipient {
				t.Fatalf("reply_to = %v, want %s", got.ReplyToRecipient, v.ReplyAgeRecipient)
			}
			if got.AlgorandTxID != v.TxID || got.TicketID != v.TicketID {
				t.Fatalf("ids = (%q, %q), want (%q, %q)", got.AlgorandTxID, got.TicketID, v.TxID, v.TicketID)
			}
			if gotTag := hex.EncodeToString(got.AdmissionTag); gotTag != r.AdmissionTagHex {
				t.Fatalf("admission tag = %q, want %q", gotTag, r.AdmissionTagHex)
			}
			if got.OpenGroup != r.OpenGroup {
				t.Fatalf("open_group = %q, want %q", got.OpenGroup, r.OpenGroup)
			}
			if got.NeutralNames != r.NeutralNames {
				t.Fatalf("neutral names = %v, want %v", got.NeutralNames, r.NeutralNames)
			}
		})
		if r.AdmissionTagHex != "" {
			seenTag = true
		} else {
			seenNoTag = true
		}
		if r.OpenGroup != "" && !r.NeutralNames {
			seenOpenGroup = true
		}
		if r.OpenGroup != "" && r.NeutralNames {
			seenNeutral = true
		}
	}
	if !seenTag || !seenNoTag || !seenOpenGroup || !seenNeutral {
		t.Fatalf("fixture must carry a request with and without an admission tag, and an open group under each set of names (with=%v without=%v open_group=%v neutral=%v)", seenTag, seenNoTag, seenOpenGroup, seenNeutral)
	}

	for name, ack := range map[string]struct {
		json    string
		neutral bool
	}{
		"settle_ack":         {v.SettleAckEnvelopeJSON, false},
		"settle_ack_neutral": {v.SettleAckNeutralEnvelopeJSON, true},
	} {
		t.Run(name, func(t *testing.T) {
			got, err := wire.OpenSettleAck([]byte(ack.json), node)
			if err != nil {
				t.Fatalf("open TS-sealed settle ack: %v", err)
			}
			want := wire.SettleAck{TicketID: v.SettleAckTicketID, SettleGroup: v.SettleAckGroup, NeutralNames: ack.neutral}
			if got != want || want.SettleGroup == "" {
				t.Fatalf("settle ack = %+v, want %+v", got, want)
			}
		})
	}

	if len(v.RefusedRequests) == 0 || len(v.RefusedSettleAcks) == 0 {
		t.Fatalf("fixture carries %d refused requests and %d refused acks; both must be non-empty", len(v.RefusedRequests), len(v.RefusedSettleAcks))
	}
	for _, r := range v.RefusedRequests {
		t.Run("refused_request_"+r.Name, func(t *testing.T) {
			if got, err := wire.DecryptRequest([]byte(r.EnvelopeJSON), node); err == nil || !strings.Contains(err.Error(), "disagree") {
				t.Fatalf("DecryptRequest = %+v, %v; want a disagreement refusal", got, err)
			}
		})
	}
	for _, r := range v.RefusedSettleAcks {
		t.Run("refused_settle_ack_"+r.Name, func(t *testing.T) {
			if got, err := wire.OpenSettleAck([]byte(r.EnvelopeJSON), node); err == nil || !strings.Contains(err.Error(), "disagree") {
				t.Fatalf("OpenSettleAck = %+v, %v; want a disagreement refusal", got, err)
			}
		})
	}

	t.Run("reserve_request", func(t *testing.T) {
		got, err := wire.OpenReserveRequest([]byte(v.ReserveRequestEnvelopeJSON), node)
		if err != nil {
			t.Fatalf("open TS-sealed reserve request: %v", err)
		}
		if want := mustHex(t, v.ReserveRequestBodyHex); !bytes.Equal(got, want) {
			t.Fatalf("reserve body = %q, want %q", got, want)
		}
	})

	keyBytes := mustHex(t, v.ResponseKeyHex)
	if len(keyBytes) != wire.ResponseKeySize {
		t.Fatalf("response_key_hex is %d bytes, want %d", len(keyBytes), wire.ResponseKeySize)
	}
	var key [wire.ResponseKeySize]byte
	copy(key[:], keyBytes)

	t.Run("wrapped_response_key", func(t *testing.T) {
		got, err := wire.UnwrapResponseKey(v.WrappedKeyB64, reply)
		if err != nil {
			t.Fatalf("unwrap TS-wrapped key: %v", err)
		}
		if !bytes.Equal(got[:], key[:]) {
			t.Fatalf("unwrapped key = %x, want %x", got, key)
		}
	})

	t.Run("body_envelope", func(t *testing.T) {
		got, err := wire.DecryptBody([]byte(v.BodyEnvelopeJSON), key, v.TxID, v.TicketID)
		if err != nil {
			t.Fatalf("open TS-sealed body: %v", err)
		}
		if want := mustHex(t, v.BodyPlaintextHex); !bytes.Equal(got, want) {
			t.Fatalf("body plaintext = %q, want %q", got, want)
		}
	})

	if len(v.Frames) == 0 || len(v.Headers) == 0 {
		t.Fatalf("fixture carries %d frames and %d headers; both must be non-empty", len(v.Frames), len(v.Headers))
	}
	for _, f := range v.Frames {
		t.Run("frame_"+hex.EncodeToString([]byte{byte(f.Index)}), func(t *testing.T) {
			got, err := wire.DecryptSSEDataValue([]byte(f.DataB64), key, v.TxID, v.TicketID, f.Index)
			if err != nil {
				t.Fatalf("open TS-sealed frame %d: %v", f.Index, err)
			}
			if want := mustHex(t, f.PlaintextHex); !bytes.Equal(got, want) {
				t.Fatalf("frame %d plaintext = %q, want %q", f.Index, got, want)
			}
			if _, err := wire.DecryptSSEDataValue([]byte(f.DataB64), key, v.TxID, v.TicketID, f.Index+1); err == nil {
				t.Fatalf("frame %d opened at index %d — frame_index is not bound", f.Index, f.Index+1)
			}
		})
	}
	// The header name is bound into the AAD, so it must be compared to Go's own
	// constant: opening with the name the fixture carries would let TS and Go
	// disagree on it and still agree on every artifact.
	wantNames := map[string]int{wire.SealedHeaderReceipt: 0, wire.SealedHeaderSettleGroup: 0}
	for _, h := range v.Headers {
		if _, ok := wantNames[h.Name]; !ok {
			t.Fatalf("TS sealed a header named %q; Go knows only %q and %q", h.Name, wire.SealedHeaderReceipt, wire.SealedHeaderSettleGroup)
		}
		wantNames[h.Name]++
	}
	for name, n := range wantNames {
		if n != 1 {
			t.Fatalf("fixture carries %d %q headers, want exactly 1", n, name)
		}
	}
	for _, h := range v.Headers {
		t.Run("header_"+h.Name, func(t *testing.T) {
			got, err := wire.OpenSealedHeader(h.ValueB64, key, v.TxID, v.TicketID, h.Name)
			if err != nil {
				t.Fatalf("open TS-sealed header %s: %v", h.Name, err)
			}
			if want := mustHex(t, h.PlaintextHex); !bytes.Equal(got, want) {
				t.Fatalf("header %s plaintext = %q, want %q", h.Name, got, want)
			}
		})
	}
}
